use std::path::PathBuf;
use ts_rs::TS;
fn main() -> anyhow::Result<()> {
    let directory = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../../packages/shared/src/generated/rust");
    std::fs::create_dir_all(&directory)?;
    let declaration = format!(
        "// Generated by cargo run -p zora-api --bin export-types. Do not edit.\nexport {}\n",
        zora_api::user::UserDto::decl(&ts_rs::Config::default())
    );
    std::fs::write(directory.join("UserDto.ts"), declaration)?;
    let icon = format!(
        "// Generated by cargo run -p zora-api --bin export-types. Do not edit.\nexport {}\n",
        zora_api::asset_icon::IconResponse::decl(&ts_rs::Config::default())
    );
    std::fs::write(directory.join("IconResponse.ts"), icon)?;
    Ok(())
}
